from gems26.submission import prediction_digest, validate_submission

REPO = "https://github.com/buffedlizard55-lab/GEMSDOE26"
ESC = html.escape


def csv_file(path, rows):
    if not rows:
        raise ValueError("No CSV rows")
    with path.open("w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0]), lineterminator="\n")
        w.writeheader()
        w.writerows(rows)


def link(href, label, css="", external=False, download=False):
    if href is None:
        return ESC(str(label))
    attributes = (' target="_blank" rel="noopener noreferrer"' if external else '') + (' download' if download else '')
    return f'<a href="{ESC(str(href), quote=True)}" class="{ESC(css)}"{attributes}>{ESC(str(label))}</a>'


def preview(path: Path, output: Path):
    with rasterio.open(path) as ds:
        image = ds.read(1)
    valid, positive = np.isfinite(image), np.nan_to_num(image) > 0
    # Each 6x6 overview block is positive if ANY original cell is positive.
    factor = 6
    pad = ((0, (-HEIGHT) % factor), (0, (-WIDTH) % factor))
    small_shape = ((HEIGHT + pad[0][1]) // factor, factor, (WIDTH + pad[1][1]) // factor, factor)
    v = np.pad(valid, pad).reshape(small_shape).max(axis=(1, 3))
    p = np.pad(positive, pad).reshape(small_shape).max(axis=(1, 3))
    rgba = np.zeros((*v.shape, 4), np.uint8)
    rgba[v] = [196, 207, 177, 255]
    rgba[p] = [161, 78, 44, 255]
    Image.fromarray(rgba).save(output, optimize=True)


